package android.database.sqlite;
import java.sql.*;import java.util.*;import android.database.Cursor;import android.content.ContentValues;
public class SQLiteDatabase {
 public static final int CONFLICT_REPLACE=5,CONFLICT_IGNORE=4;final Connection connection;boolean active,successful;
 public SQLiteDatabase(java.io.File path){try{connection=DriverManager.getConnection("jdbc:sqlite:"+path);try(Statement s=connection.createStatement()){s.execute("PRAGMA busy_timeout=5000");}}catch(Exception e){throw new SQLiteException(e);}}
 public boolean inTransaction(){return active;}public void beginTransaction(){if(active)throw new SQLiteException("nested transaction in test contract");try{connection.setAutoCommit(false);active=true;successful=false;}catch(Exception e){throw new SQLiteException(e);}}public void beginTransactionNonExclusive(){beginTransaction();}public void setTransactionSuccessful(){successful=true;}public void endTransaction(){try{if(successful)connection.commit();else connection.rollback();connection.setAutoCommit(true);}catch(Exception e){throw new SQLiteException(e);}finally{active=false;successful=false;}}
 public void execSQL(String sql){execSQL(sql,null);}public void execSQL(String sql,Object[] args){try(PreparedStatement statement=connection.prepareStatement(sql)){bind(statement,args);statement.execute();}catch(Exception e){throw new SQLiteException(e);}}
 static void bind(PreparedStatement p,Object[] a)throws Exception{if(a!=null)for(int i=0;i<a.length;i++)p.setObject(i+1,a[i]);}
 public Cursor rawQuery(String sql,String[] args){try(PreparedStatement p=connection.prepareStatement(sql)){bind(p,args);try(ResultSet result=p.executeQuery()){List<Object[]> rows=new ArrayList<>();ResultSetMetaData m=result.getMetaData();String[] names=new String[m.getColumnCount()];for(int i=0;i<names.length;i++)names[i]=m.getColumnLabel(i+1);while(result.next()){Object[] row=new Object[names.length];for(int i=0;i<row.length;i++)row[i]=result.getObject(i+1);rows.add(row);}return new Rows(names,rows);}}catch(Exception e){throw new SQLiteException(e);}}
 public boolean enableWriteAheadLogging(){return true;}public void disableWriteAheadLogging(){}
 public Cursor query(String table,String[] columns,String where,String[] args,String group,String having,String order){return query(table,columns,where,args,group,having,order,null);}
 public Cursor query(String table,String[] columns,String where,String[] args,String group,String having,String order,String limit){
  String sql="SELECT "+(columns==null?"*":String.join(",",columns))+" FROM "+table+(where==null?"":" WHERE "+where)+(order==null?"":" ORDER BY "+order)+(limit==null?"":" LIMIT "+limit);
  return rawQuery(sql,args);
 }
 public long insertOrThrow(String table,String empty,ContentValues values){return insertWithOnConflict(table,empty,values,0);}public long insertWithOnConflict(String table,String empty,ContentValues values,int conflict){String columns=String.join(",",values.values.keySet());String placeholders=String.join(",",Collections.nCopies(values.values.size(),"?"));String mode=conflict==CONFLICT_REPLACE?" OR REPLACE":conflict==CONFLICT_IGNORE?" OR IGNORE":"";try(PreparedStatement p=connection.prepareStatement("INSERT"+mode+" INTO "+table+"("+columns+") VALUES("+placeholders+")")){bind(p,values.values.values().toArray());if(p.executeUpdate()==0)return -1;try(Cursor c=rawQuery("SELECT last_insert_rowid()",null)){c.moveToFirst();return c.getLong(0);}}catch(Exception e){throw new SQLiteException(e);}}
 public int delete(String table,String where,String[] args){return executeChange("DELETE FROM "+table+(where==null?"":" WHERE "+where),args);}public int update(String table,ContentValues values,String where,String[] args){List<String> columns=new ArrayList<>();for(String key:values.values.keySet())columns.add(key+"=?");List<Object> all=new ArrayList<>(values.values.values());if(args!=null)Collections.addAll(all,args);return executeChange("UPDATE "+table+" SET "+String.join(",",columns)+(where==null?"":" WHERE "+where),all.toArray());}int executeChange(String sql,Object[] args){try(PreparedStatement p=connection.prepareStatement(sql)){bind(p,args);return p.executeUpdate();}catch(Exception e){throw new SQLiteException(e);}}
 public boolean isReadOnly(){return false;}public void close(){try{connection.close();}catch(Exception e){throw new SQLiteException(e);}}
 static class Rows implements Cursor {final String[] names;final List<Object[]> rows;int at=-1;Rows(String[] n,List<Object[]> r){names=n;rows=r;}public boolean moveToFirst(){at=0;return at<rows.size();}public boolean moveToNext(){at++;return at<rows.size();}public int getCount(){return rows.size();}public String getString(int i){Object v=rows.get(at)[i];return v==null?null:v.toString();}public int getInt(int i){return (int)getLong(i);}public long getLong(int i){Object v=rows.get(at)[i];return v==null?0:Long.parseLong(v.toString());}public boolean isNull(int i){return rows.get(at)[i]==null;}public int getColumnCount(){return names.length;}public String getColumnName(int i){return names[i];}public boolean isReadOnly(){return false;}public void close(){}}
}
